// Claude's review tests for A15 (import an OpenAPI or Swagger file). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { detectOpenApi, importOpenApi, openApiSummaryText, parseSpecText, sampleFromSchema } from './openapiImport';

const ids = () => {
  let n = 0;
  return () => `id${++n}`;
};
const ORIGIN = 'http://shop.test';

const v3 = {
  openapi: '3.0.3',
  info: { title: 'Shop API', version: '1' },
  servers: [{ url: 'https://api.shop.test/v1' }],
  paths: {
    '/users/{id}': {
      parameters: [{ name: 'id', in: 'path' }],
      get: {
        operationId: 'getUser',
        responses: {
          '404': { description: 'no', content: { 'application/json': { example: { error: 'x' } } } },
          '200': { description: 'ok', content: { 'application/json': { example: { id: 1, name: 'Anna' } } } },
        },
      },
      delete: { summary: 'Remove a user', responses: { '204': { description: 'gone' } } },
    },
    '/orders/{orderId}/items/{itemId}': {
      put: {
        responses: {
          '201': { content: { 'application/json': { examples: { first: { value: { ok: true } }, second: { value: { ok: false } } } } } },
        },
      },
    },
    '/pets': {
      get: {
        responses: { default: { content: { 'application/json': { schema: { $ref: '#/components/schemas/PetList' } } } } },
      },
      post: { responses: { '400': { description: 'bad' } } },
    },
    '/health': { get: { responses: { '200': { content: { 'text/plain': { example: 'OK' } } } } } },
  },
  components: {
    schemas: {
      PetList: { type: 'array', items: { $ref: '#/components/schemas/Pet' } },
      Pet: {
        type: 'object',
        required: ['id'],
        properties: {
          id: { type: 'integer' },
          name: { type: 'string', example: 'Rex' },
          kind: { type: 'string', enum: ['dog', 'cat'] },
          born: { type: 'string', format: 'date' },
          tags: { type: 'array', items: { type: 'string' } },
          vaccinated: { type: 'boolean' },
        },
      },
    },
  },
};

describe('detectOpenApi', () => {
  it('knows OpenAPI 3 and Swagger 2 by their version key and paths', () => {
    expect(detectOpenApi(v3)).toBe(true);
    expect(detectOpenApi({ swagger: '2.0', paths: {} })).toBe(true);
    expect(detectOpenApi({ openapi: '3.1.0' })).toBe(false);
    expect(detectOpenApi({ log: { entries: [] } })).toBe(false);
  });
});

describe('parseSpecText', () => {
  it('reads JSON and YAML', () => {
    expect(parseSpecText('{"openapi":"3.0.0","paths":{}}')).toEqual({ openapi: '3.0.0', paths: {} });
    expect(parseSpecText('openapi: 3.0.0\npaths:\n  /a:\n    get:\n      responses: {}\n')).toEqual({ openapi: '3.0.0', paths: { '/a': { get: { responses: {} } } } });
  });
  it('returns null for text that is neither', () => {
    expect(parseSpecText('{ not json: [')).toBeNull();
  });
});

describe('importOpenApi: OpenAPI 3', () => {
  const r = importOpenApi(v3, ORIGIN, ids(), 5);
  if (!r.ok) throw new Error(r.error);
  const sc = r.result.project.scenarios[1]!;
  const by = (method: string, pattern: string) => sc.mocks.find((m) => m.method === method && m.urlPattern === pattern)!;

  it('one mock per operation, with the base path and :params', () => {
    expect(sc.mocks.map((m) => `${m.method} ${m.urlPattern}`)).toEqual([
      'GET /v1/users/:id',
      'DELETE /v1/users/:id',
      'PUT /v1/orders/:orderId/items/:itemId',
      'GET /v1/pets',
      'POST /v1/pets',
      'GET /v1/health',
    ]);
    expect(r.ok && r.result.summary).toEqual({ mocks: 6, operations: 6 });
  });

  it('names a mock by operationId, then summary, then method and path', () => {
    expect(by('GET', '/v1/users/:id').name).toBe('getUser');
    expect(by('DELETE', '/v1/users/:id').name).toBe('Remove a user');
    expect(by('PUT', '/v1/orders/:orderId/items/:itemId').name).toBe('PUT /orders/{orderId}/items/{itemId}');
  });

  it('answers the first 2xx with its example', () => {
    const m = by('GET', '/v1/users/:id');
    expect(m.response.status).toBe(200);
    expect(JSON.parse(m.response.body)).toEqual({ id: 1, name: 'Anna' });
    expect(m.response.headers).toEqual({ 'content-type': 'application/json' });
  });

  it('takes the first of several examples', () => {
    const m = by('PUT', '/v1/orders/:orderId/items/:itemId');
    expect(m.response.status).toBe(201);
    expect(JSON.parse(m.response.body)).toEqual({ ok: true });
  });

  it('a 2xx with no content gives an empty body and no content-type', () => {
    const m = by('DELETE', '/v1/users/:id');
    expect(m.response.status).toBe(204);
    expect(m.response.body).toBe('');
    expect(m.response.headers).toEqual({});
  });

  it('falls back to default, and builds a sample from the schema', () => {
    const m = by('GET', '/v1/pets');
    expect(m.response.status).toBe(200);
    expect(JSON.parse(m.response.body)).toEqual([{ id: 0, name: 'Rex', kind: 'dog', born: '2026-01-01', tags: ['string'], vaccinated: true }]);
  });

  it('with no 2xx and no default, answers 200 with an empty body', () => {
    const m = by('POST', '/v1/pets');
    expect(m.response.status).toBe(200);
    expect(m.response.body).toBe('');
  });

  it('a text example is sent as written', () => {
    const m = by('GET', '/v1/health');
    expect(m.response.body).toBe('OK');
    expect(m.response.headers).toEqual({ 'content-type': 'text/plain' });
  });

  it('makes an empty Default and one active scenario named after the title', () => {
    const p = r.ok ? r.result.project : null;
    expect(p!.scenarios[0]!.mocks).toEqual([]);
    expect(sc.name).toBe('Shop API');
    expect(p!.activeScenarioId).toBe(sc.id);
    expect(p!.origins).toEqual([ORIGIN]);
    expect(sc.mocks.every((m) => m.source === 'manual' && m.enabled && m.response.bodyEncoding === 'text' && m.response.delayMs === 0)).toBe(true);
  });

  it('a relative server URL is a base path too; no servers means none', () => {
    const rel = importOpenApi({ ...v3, servers: [{ url: '/api' }] }, ORIGIN, ids(), 5);
    expect(rel.ok && rel.result.project.scenarios[1]!.mocks[0]!.urlPattern).toBe('/api/users/:id');
    const none = importOpenApi({ ...v3, servers: undefined }, ORIGIN, ids(), 5);
    expect(none.ok && none.result.project.scenarios[1]!.mocks[0]!.urlPattern).toBe('/users/:id');
    const slash = importOpenApi({ ...v3, servers: [{ url: 'https://x.test/' }] }, ORIGIN, ids(), 5);
    expect(slash.ok && slash.result.project.scenarios[1]!.mocks[0]!.urlPattern).toBe('/users/:id');
  });
});

describe('importOpenApi: Swagger 2', () => {
  const sw = {
    swagger: '2.0',
    info: { title: 'Old API' },
    basePath: '/api/v2',
    produces: ['application/json'],
    paths: {
      '/things/{id}': {
        get: { responses: { '200': { examples: { 'application/json': { id: 7 } } } } },
        patch: { responses: { '200': { schema: { $ref: '#/definitions/Thing' } } } },
      },
    },
    definitions: { Thing: { type: 'object', properties: { id: { type: 'number' }, label: { type: 'string', default: 'hello' } } } },
  };
  it('reads basePath, examples and definitions', () => {
    const r = importOpenApi(sw, ORIGIN, ids(), 5);
    if (!r.ok) throw new Error(r.error);
    const [get, patch] = r.result.project.scenarios[1]!.mocks;
    expect(get!.urlPattern).toBe('/api/v2/things/:id');
    expect(JSON.parse(get!.response.body)).toEqual({ id: 7 });
    expect(get!.response.headers).toEqual({ 'content-type': 'application/json' });
    expect(JSON.parse(patch!.response.body)).toEqual({ id: 0, label: 'hello' });
    expect(r.result.project.scenarios[1]!.name).toBe('Old API');
  });
});

describe('sampleFromSchema', () => {
  const root = {
    components: {
      schemas: {
        Node: { type: 'object', properties: { value: { type: 'integer', minimum: 3 }, next: { $ref: '#/components/schemas/Node' } } },
        Base: { type: 'object', properties: { a: { type: 'string' } } },
      },
    },
  };
  it('follows a cycle to depth 6 and then stops with null', () => {
    const s = sampleFromSchema({ $ref: '#/components/schemas/Node' }, root) as Record<string, unknown>;
    let depth = 0;
    let cur: unknown = s;
    while (cur && typeof cur === 'object') {
      depth++;
      cur = (cur as Record<string, unknown>).next;
    }
    expect(depth).toBe(6);
    expect(cur).toBeNull();
    expect(s.value).toBe(3);
  });
  it('formats, allOf, oneOf and a missing ref', () => {
    expect(sampleFromSchema({ type: 'string', format: 'date-time' }, root)).toBe('2026-01-01T00:00:00Z');
    expect(sampleFromSchema({ type: 'string', format: 'email' }, root)).toBe('user@example.com');
    expect(sampleFromSchema({ type: 'string', format: 'uuid' }, root)).toBe('00000000-0000-4000-8000-000000000000');
    expect(sampleFromSchema({ type: 'string', format: 'uri' }, root)).toBe('https://example.com');
    expect(sampleFromSchema({ allOf: [{ $ref: '#/components/schemas/Base' }, { type: 'object', properties: { b: { type: 'boolean' } } }] }, root)).toEqual({ a: 'string', b: true });
    expect(sampleFromSchema({ oneOf: [{ type: 'number' }, { type: 'string' }] }, root)).toBe(0);
    expect(sampleFromSchema({ anyOf: [{ type: 'boolean' }] }, root)).toBe(true);
    expect(sampleFromSchema({ $ref: '#/components/schemas/Nope' }, root)).toBeNull();
    expect(sampleFromSchema({ properties: { x: { type: 'string' } } }, root)).toEqual({ x: 'string' });
    expect(sampleFromSchema({ type: 'string', example: 'given', default: 'd', enum: ['e'] }, root)).toBe('given');
    expect(sampleFromSchema({ type: 'string', default: 'd', enum: ['e'] }, root)).toBe('d');
    expect(sampleFromSchema({ type: 'null' }, root)).toBeNull();
  });
});

describe('errors and summary', () => {
  it('a spec with no operations is an error', () => {
    const r = importOpenApi({ openapi: '3.0.0', info: { title: 'x' }, paths: {} }, ORIGIN, ids(), 5);
    expect(r.ok).toBe(false);
  });
  it('summary text', () => {
    expect(openApiSummaryText({ mocks: 6, operations: 6 })).toBe('6 mocks from 6 operations');
    expect(openApiSummaryText({ mocks: 1, operations: 1 })).toBe('1 mock from 1 operation');
  });
});

describe('more schema and media cases', () => {
  const root = { components: { schemas: { Base: { type: 'object', properties: { a: { type: 'string' } } } } } };
  it('allOf keeps the properties written beside it', () => {
    expect(sampleFromSchema({ allOf: [{ $ref: '#/components/schemas/Base' }], properties: { c: { type: 'integer' } } }, root)).toEqual({ a: 'string', c: 0 });
  });
  it('a +json media type is JSON: a string example is sent as a JSON string', () => {
    const doc = {
      openapi: '3.0.0', info: { title: 't' },
      paths: { '/p': { get: { responses: { '200': { content: { 'application/vnd.api+json': { example: 'hi' } } } } } } },
    };
    const r = importOpenApi(doc, ORIGIN, ids(), 5);
    if (!r.ok) throw new Error(r.error);
    expect(r.result.project.scenarios[1]!.mocks[0]!.response.body).toBe('"hi"');
  });
  it('default and enum also apply to a schema reached through $ref', () => {
    const r2 = { components: { schemas: { D: { type: 'string', default: 'dd' }, E: { type: 'string', enum: ['e1', 'e2'] } } } };
    expect(sampleFromSchema({ $ref: '#/components/schemas/D' }, r2)).toBe('dd');
    expect(sampleFromSchema({ $ref: '#/components/schemas/E' }, r2)).toBe('e1');
  });
});
